CREATE TABLE public.ai_provider_finance (brand_id uuid NOT NULL REFERENCES public.brands(id) ON DELETE CASCADE, provider text NOT NULL, blocked boolean NOT NULL DEFAULT false, reason text, generation bigint NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(brand_id,provider));
GRANT SELECT ON public.ai_provider_finance TO authenticated; GRANT ALL ON public.ai_provider_finance TO service_role; REVOKE ALL ON public.ai_provider_finance FROM anon, PUBLIC;
ALTER TABLE public.ai_provider_finance ENABLE ROW LEVEL SECURITY;
CREATE POLICY finance_member_read ON public.ai_provider_finance FOR SELECT TO authenticated USING(public.is_brand_member(brand_id,auth.uid()));
CREATE TABLE public.ai_budget_alert_settings (brand_id uuid PRIMARY KEY REFERENCES public.brands(id) ON DELETE CASCADE, thresholds integer[] NOT NULL DEFAULT ARRAY[80,95,100], created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.ai_budget_alert_settings TO authenticated; GRANT ALL ON public.ai_budget_alert_settings TO service_role; REVOKE ALL ON public.ai_budget_alert_settings FROM anon,PUBLIC;
ALTER TABLE public.ai_budget_alert_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY budget_admin_read ON public.ai_budget_alert_settings FOR SELECT TO authenticated USING(public.is_super_admin(auth.uid()) OR EXISTS(SELECT 1 FROM public.brand_members m WHERE m.brand_id=ai_budget_alert_settings.brand_id AND m.user_id=auth.uid() AND m.is_active AND m.role IN ('owner','admin')));
CREATE POLICY budget_admin_write ON public.ai_budget_alert_settings FOR ALL TO authenticated USING(public.is_super_admin(auth.uid()) OR EXISTS(SELECT 1 FROM public.brand_members m WHERE m.brand_id=ai_budget_alert_settings.brand_id AND m.user_id=auth.uid() AND m.is_active AND m.role IN ('owner','admin'))) WITH CHECK(public.is_super_admin(auth.uid()) OR EXISTS(SELECT 1 FROM public.brand_members m WHERE m.brand_id=ai_budget_alert_settings.brand_id AND m.user_id=auth.uid() AND m.is_active AND m.role IN ('owner','admin')));
CREATE TABLE public.ai_finance_alert_events (brand_id uuid NOT NULL REFERENCES public.brands(id) ON DELETE CASCADE, event_key text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(brand_id,event_key));
GRANT ALL ON public.ai_finance_alert_events TO service_role; REVOKE ALL ON public.ai_finance_alert_events FROM anon,authenticated,PUBLIC;
ALTER TABLE public.ai_finance_alert_events ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.ai_finance_validate_settings() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF cardinality(NEW.thresholds)<>3 OR NEW.thresholds[1]<1 OR NEW.thresholds[1]>=NEW.thresholds[2] OR NEW.thresholds[2]>=NEW.thresholds[3] OR NEW.thresholds[3]>100 OR array_position(NEW.thresholds,NULL) IS NOT NULL THEN RAISE EXCEPTION 'Faixas inválidas'; END IF; NEW.updated_at=now(); RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.ai_finance_validate_settings() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER ai_budget_settings_validate BEFORE INSERT OR UPDATE ON public.ai_budget_alert_settings FOR EACH ROW EXECUTE FUNCTION public.ai_finance_validate_settings();
CREATE OR REPLACE FUNCTION public.ai_finance_notify(_brand uuid,_key text,_title text,_body text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.ai_finance_alert_events(brand_id,event_key) VALUES(_brand,_key) ON CONFLICT DO NOTHING; IF NOT FOUND THEN RETURN; END IF; INSERT INTO public.notifications(user_id,brand_id,kind,title,body,href,payload) SELECT m.user_id,_brand,'system',_title,_body,'/connections',jsonb_build_object('source','ai_finance') FROM public.brand_members m WHERE m.brand_id=_brand AND m.is_active AND m.role IN ('owner','admin'); END $$;
REVOKE ALL ON FUNCTION public.ai_finance_notify(uuid,text,text,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.ai_finance_notify(uuid,text,text,text) TO service_role;
CREATE OR REPLACE FUNCTION public.ai_finance_block(_brand uuid,_provider text,_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE _generation bigint; BEGIN IF _provider NOT IN ('openai','anthropic','gemini','groq') OR _reason NOT IN ('provider_credit','provider_financial_limit') THEN RAISE EXCEPTION 'Estado inválido'; END IF; INSERT INTO public.ai_provider_finance(brand_id,provider,blocked,reason,generation) VALUES(_brand,_provider,true,_reason,1) ON CONFLICT(brand_id,provider) DO UPDATE SET blocked=true,reason=excluded.reason,generation=ai_provider_finance.generation+CASE WHEN ai_provider_finance.blocked THEN 0 ELSE 1 END,updated_at=now() RETURNING generation INTO _generation; PERFORM public.ai_finance_notify(_brand,'provider:'||_provider||':'||_generation,'IA sem crédito ou limite financeiro atingido',_provider||': solicite a reposição do saldo ou revisão do limite financeiro no provedor.'); END $$;
REVOKE ALL ON FUNCTION public.ai_finance_block(uuid,text,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.ai_finance_block(uuid,text,text) TO service_role;
CREATE OR REPLACE FUNCTION public.ai_budget_evaluate(_brand uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE _budget numeric; _spent numeric; _thresholds integer[]; _threshold integer; _month text; _start timestamptz; BEGIN PERFORM pg_advisory_xact_lock(hashtextextended(_brand::text,771)); SELECT monthly_budget_usd INTO _budget FROM public.brand_connections WHERE brand_id=_brand; IF coalesce(_budget,0)<=0 THEN RETURN; END IF; _start=date_trunc('month',now() AT TIME ZONE 'America/Sao_Paulo') AT TIME ZONE 'America/Sao_Paulo'; _month=to_char(_start AT TIME ZONE 'America/Sao_Paulo','YYYY-MM'); SELECT coalesce(sum(cost_usd),0) INTO _spent FROM public.brand_ai_usage WHERE brand_id=_brand AND created_at>=_start; SELECT thresholds INTO _thresholds FROM public.ai_budget_alert_settings WHERE brand_id=_brand; FOREACH _threshold IN ARRAY coalesce(_thresholds,ARRAY[80,95,100]) LOOP IF _spent*100>=_budget*_threshold THEN PERFORM public.ai_finance_notify(_brand,'budget:'||_month||':'||_threshold,'IA: '||_threshold||'% do orçamento mensal','Consumo estimado registrado no Unitos: US$ '||round(_spent,2)||' de US$ '||round(_budget,2)||'. Não representa saldo do provedor.'); END IF; END LOOP; END $$;
REVOKE ALL ON FUNCTION public.ai_budget_evaluate(uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.ai_budget_evaluate(uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.ai_finance_usage_trigger() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM public.ai_budget_evaluate(NEW.brand_id); RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.ai_finance_usage_trigger() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER ai_usage_budget_alert AFTER INSERT ON public.brand_ai_usage FOR EACH ROW EXECUTE FUNCTION public.ai_finance_usage_trigger();
CREATE TRIGGER ai_connection_budget_alert AFTER INSERT OR UPDATE OF monthly_budget_usd ON public.brand_connections FOR EACH ROW EXECUTE FUNCTION public.ai_finance_usage_trigger();
CREATE TRIGGER ai_threshold_budget_alert AFTER INSERT OR UPDATE ON public.ai_budget_alert_settings FOR EACH ROW EXECUTE FUNCTION public.ai_finance_usage_trigger();
CREATE TRIGGER ai_finance_updated_at BEFORE UPDATE ON public.ai_provider_finance FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();
CREATE TRIGGER ai_finance_events_updated_at BEFORE UPDATE ON public.ai_finance_alert_events FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();